#!/usr/bin/env bash
# Question 16: Pods of ${Q16_NS} in order. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/sort
mkdir -p /opt/course/sort
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q16_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q16_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q16_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q16_NS}" delete pod --all --wait=true >/dev/null 2>&1 || true
for name in $(shuf -e zeta-api alpha-worker mid-cache beta-sync omega-report); do
  cmd='"sleep","infinity"'
  [[ "$name" == beta-sync || "$name" == omega-report ]] && cmd='"sh","-c","exit 1"'
  kubectl apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"$name"'","namespace":"'"${Q16_NS}"'"},"spec":{"restartPolicy":"Never","containers":[{"name":"c","image":"busybox:1.36","command":['"$cmd"']}]}}' >/dev/null
  sleep 2
done
kubectl -n "${Q16_NS}" wait --for=jsonpath='{.status.phase}'=Running pod/zeta-api pod/alpha-worker pod/mid-cache --timeout=120s >/dev/null
: "${Q16_NS}"
